using System;
using System.Collections.Generic;
using System.Net.WebSockets;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace SecureChat.Server
{
    public class UserProfile
    {
        public string DisplayName { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }
        public string Role { get; set; } = "user";
        public bool IsVerified { get; set; } = false;
        public int TrustScore { get; set; } = 0;
        public string InternalNote { get; set; }
    }

    public class ProfileUpdateRequest
    {
        public string DisplayName { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }
    }

    public interface IProfileBinder
    {
        UserProfile ApplyUpdate(UserProfile existing, JsonElement payload, string[] allowedFields);
    }

    public class ReflectionProfileBinder : IProfileBinder
    {
        private static readonly HashSet<string> ProtectedFields = new(StringComparer.OrdinalIgnoreCase)
        {
            "Role", "IsVerified", "TrustScore", "InternalNote"
        };

        public UserProfile ApplyUpdate(UserProfile existing, JsonElement payload, string[] allowedFields)
        {
            var allowedSet = new HashSet<string>(allowedFields, StringComparer.OrdinalIgnoreCase);
            var profileType = typeof(UserProfile);

            foreach (var prop in payload.EnumerateObject())
            {
                var propertyInfo = profileType.GetProperty(prop.Name);
                if (propertyInfo == null) continue;

                if (IsFieldPermitted(prop.Name, allowedSet))
                {
                    var value = DeserializeValue(prop.Value, propertyInfo.PropertyType);
                    propertyInfo.SetValue(existing, value);
                }
            }
            return existing;
        }

        private bool IsFieldPermitted(string fieldName, HashSet<string> allowedSet)
        {
            // Defense in depth: block protected fields AND require allowlist
            if (ProtectedFields.Contains(fieldName))
                return false;
            return allowedSet.Contains(fieldName);
        }

        private object DeserializeValue(JsonElement element, Type targetType)
        {
            if (targetType == typeof(string)) return element.GetString();
            if (targetType == typeof(bool)) return element.GetBoolean();
            if (targetType == typeof(int)) return element.GetInt32();
            return null;
        }
    }

    public class WebSocketHandler
    {
        private readonly IProfileBinder _binder;
        private readonly Dictionary<string, UserProfile> _profiles = new();
        private const int MaxMessageBytes = 4096;

        private static readonly string[] UserAllowedFields = { "DisplayName", "AvatarUrl", "Bio" };
        private static readonly string[] AdminAllowedFields = { "DisplayName", "AvatarUrl", "Bio", "Role", "IsVerified", "TrustScore", "InternalNote" };

        public WebSocketHandler(IProfileBinder binder)
        {
            _binder = binder;
        }

        public async Task HandleConnection(HttpContext context, WebSocket webSocket)
        {
            // Derive identity from authenticated claims, never from spoofable headers.
            var userId = ResolveUserId(context);
            if (userId == null)
            {
                await webSocket.CloseAsync(WebSocketCloseStatus.PolicyViolation, "unauthenticated", CancellationToken.None);
                return;
            }

            var userRole = ResolveRole(context);

            if (!_profiles.ContainsKey(userId))
                _profiles[userId] = new UserProfile { DisplayName = "User_" + userId };

            var buffer = new byte[MaxMessageBytes];
            while (webSocket.State == WebSocketState.Open)
            {
                var result = await webSocket.ReceiveAsync(buffer, CancellationToken.None);
                if (result.MessageType == WebSocketMessageType.Close) break;

                // Reject fragmented/oversized messages to avoid processing truncated data.
                if (!result.EndOfMessage)
                {
                    await webSocket.CloseAsync(WebSocketCloseStatus.MessageTooBig, "message too large", CancellationToken.None);
                    break;
                }

                var message = Encoding.UTF8.GetString(buffer, 0, result.Count);
                var response = ProcessMessage(userId, userRole, message);

                var responseBytes = Encoding.UTF8.GetBytes(response);
                await webSocket.SendAsync(responseBytes, WebSocketMessageType.Text, true, CancellationToken.None);
            }
        }

        private string ResolveUserId(HttpContext context)
        {
            // Trust only authenticated identity, never the X-User-Id header.
            return context.User?.FindFirst("sub")?.Value
                ?? context.User?.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
        }

        private string ResolveRole(HttpContext context)
        {
            // Only trust authenticated claims, never proxy headers for authorization
            return context.User?.FindFirst("role")?.Value ?? "user";
        }

        private string ProcessMessage(string userId, string userRole, string rawMessage)
        {
            try
            {
                var doc = JsonDocument.Parse(rawMessage);
                var root = doc.RootElement;
                var action = root.GetProperty("action").GetString();

                switch (action)
                {
                    case "update_profile":
                        return HandleProfileUpdate(userId, userRole, root.GetProperty("data"));
                    case "get_profile":
                        return JsonSerializer.Serialize(_profiles.GetValueOrDefault(userId));
                    default:
                        return JsonSerializer.Serialize(new { error = "unknown action" });
                }
            }
            catch (Exception)
            {
                // Do not leak internal exception details to the client.
                return JsonSerializer.Serialize(new { error = "invalid request" });
            }
        }

        private string HandleProfileUpdate(string userId, string userRole, JsonElement data)
        {
            var allowedFields = GetAllowedFieldsForRole(userRole);
            var profile = _profiles[userId];
            _binder.ApplyUpdate(profile, data, allowedFields);
            _profiles[userId] = profile;
            return JsonSerializer.Serialize(new { success = true, profile = _profiles[userId] });
        }

        private string[] GetAllowedFieldsForRole(string role)
        {
            return role switch
            {
                "admin" => AdminAllowedFields,
                "moderator" => AdminAllowedFields,
                _ => UserAllowedFields
            };
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddSingleton<IProfileBinder, ReflectionProfileBinder>();
            builder.Services.AddSingleton<WebSocketHandler>();

            var app = builder.Build();
            app.UseWebSockets();

            app.Map("/ws", async (HttpContext context) =>
            {
                if (context.WebSockets.IsWebSocketRequest)
                {
                    var ws = await context.WebSockets.AcceptWebSocketAsync();
                    var handler = context.RequestServices.GetRequiredService<WebSocketHandler>();
                    await handler.HandleConnection(context, ws);
                }
                else
                {
                    context.Response.StatusCode = 400;
                }
            });

            app.Run();
        }
    }
}
